package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for {@link HypergeometricDistribution#getNumericalMean()}.
 */
public class HypergeometricDistribution_getNumericalMean_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetNumericalMeanWithStandardValues() {
        // populationSize = 100, numberOfSuccesses = 20, sampleSize = 10
        // Mean = (10 * 20) / 100 = 2.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(100, 20, 10);
        double expected = 2.0;
        assertEquals(expected, distribution.getNumericalMean(), DELTA);
    }

    @Test
    public void testGetNumericalMeanWithSmallValues() {
        // populationSize = 10, numberOfSuccesses = 5, sampleSize = 2
        // Mean = (2 * 5) / 10 = 1.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(10, 5, 2);
        double expected = 1.0;
        assertEquals(expected, distribution.getNumericalMean(), DELTA);
    }

    @Test
    public void testGetNumericalMeanWithZeroSuccesses() {
        // populationSize = 100, numberOfSuccesses = 0, sampleSize = 10
        // Mean = (10 * 0) / 100 = 0.0
        // Note: Constructor might throw exception if 0 is not allowed, 
        // but based on the provided signature, we assume standard hypergeometric logic.
        // If the constructor throws NotPositiveException for 0, this test expects that.
        try {
            HypergeometricDistribution distribution = new HypergeometricDistribution(100, 0, 10);
            double expected = 0.0;
            assertEquals(expected, distribution.getNumericalMean(), DELTA);
        } catch (NotPositiveException e) {
            // If the implementation enforces strictly positive successes
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testGetNumericalMeanWithLargeValues() {
        // populationSize = 1000000, numberOfSuccesses = 500000, sampleSize = 500000
        // Mean = (500000 * 500000) / 1000000 = 250000.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(1000000, 500000, 500000);
        double expected = 250000.0;
        assertEquals(expected, distribution.getNumericalMean(), DELTA);
    }

    @Test
    public void testGetNumericalMeanResultIsDouble() {
        // populationSize = 3, numberOfSuccesses = 1, sampleSize = 1
        // Mean = (1 * 1) / 3 = 0.3333333333333333
        HypergeometricDistribution distribution = new HypergeometricDistribution(3, 1, 1);
        double expected = 1.0 / 3.0;
        assertEquals(expected, distribution.getNumericalMean(), DELTA);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructorThrowsExceptionForInvalidPopulationSize() throws Exception {
        new HypergeometricDistribution(0, 10, 5);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructorThrowsExceptionForInvalidSampleSize() throws Exception {
        new HypergeometricDistribution(100, 10, 0);
    }
}
